    "auth.forgot": "Wachtwoord vergeten?",
    "auth.err.enterEmailFirst": "Vul eerst je e-mailadres in, dan sturen we een herstellink.",
    "auth.success.resetSent": "Herstellink verstuurd! Check je e-mail om een nieuw wachtwoord in te stellen.",
    "auth.err.alreadyExists": "Dit e-mailadres heeft al een account. Ga hierboven naar “Inloggen” — of gebruik “Wachtwoord vergeten?”.",
    "auth.success.created": "Account aangemaakt! Check je e-mail om te bevestigen. Niet gevonden? Kijk in je spam.",
    "auth.err.notConfirmed": "E-mail nog niet bevestigd — klik op de link in de mail die we je stuurden. Niet gevonden? Kijk in je spam.",
    "common.backPlain": "Terug",
    "ret.title": "Retouren & herroeping",
    "ret.subtitle": "Je rechten en hoe retouren werken bij Flowva.",
    "ret.s1.h": "1. Van wie je koopt",
    "ret.s1.b": "Je koopt bij Flowva. Wij selecteren de producten, bepalen de prijs, rekenen een servicevergoeding en regelen de inkoop, quality-control en internationale verzending voor je. Flowva is de verkoper.",
    "ret.s2.h": "2. Je EU-herroepingsrecht van 14 dagen",
    "ret.s2.b": "Je mag binnen 14 dagen zonder reden herroepen. In de EU is dat je wettelijke recht — en wij hanteren dezelfde 14 dagen voor elk land waar we leveren. De 14 dagen starten op de dag dat je het item ontvangt — niet op de besteldag. Omdat items uit China verzonden worden, begint je termijn zodra het pakket aankomt. Je mag ook herroepen vóórdat het aankomt.",
    "ret.s3.h": "3. Hoe je herroept",
    "ret.s3.b": "Gebruik de pagina “Herroepen / bestelling annuleren” — geen login nodig. Geef je naam, bestelnummer en e-mailadres door. Je krijgt automatisch een bevestiging en daarna 14 dagen om het item terug te sturen.",
    "ret.s4.h": "4. Wat je terugkrijgt",
    "ret.s4.b": "Gedeeltelijke retour (je houdt een deel van de items): we betalen alleen de productprijs van de geretourneerde items terug — verzendkosten worden bij een gedeeltelijke retour niet vergoed. Volledige herroeping: productprijs plus de standaard heenverzendkosten.",
    "ret.s5.h": "5. Retourverzendkosten",
    "ret.s5.b": "Je betaalt de retourverzending zelf. We geven je een retouradres in Nederland, dus je hoeft nooit naar China terug te sturen. Binnen de EU is dat meestal €5–€10; vanuit het VK, de VS, Canada, Australië of Noorwegen doorgaans €10–€25, afhankelijk van de vervoerder. Retourneer binnen 14 dagen na je verzoek.",
    "ret.s6.h": "6. Staat van de items",
    "ret.s6.b": "Stuur items terug in originele staat (ongedragen, met labels en verpakking). We mogen je terugbetaling verminderen bij waardeverlies door gebruik dat verder gaat dan nodig om het item te beoordelen.",
    "ret.s7.h": "7. Terugbetaling",
    "ret.s7.b": "We betalen terug binnen 14 dagen nadat we het item terug hebben (of je verzendbewijs), op je Flowva-saldo.",
    "ret.s8.h": "8. Annuleren tijdens de verwerking",
    "ret.s8.b": "Vóórdat we het item hebben ingekocht: kosteloos geannuleerd, volledige terugbetaling. Nadat het is verzonden: behandeld als retour — je stuurt het naar ons NL-adres.",
    "ret.s9.h": "9. Uitgesloten items",
    "ret.s9.b": "Het 14-dagenrecht geldt niet voor maatwerk of gepersonaliseerde producten, verzegelde hygiëne-items zodra de verzegeling is verbroken, bederfelijke waren en andere wettelijk uitgesloten categorieën.",
    "ret.s10.h": "10. Defecte of verkeerde items",
    "ret.s10.b": "Elk item wordt vóór verzending gecontroleerd en gefotografeerd. Flowva dekt de retourverzending alleen als een item een echt gebrek heeft dat twee keer gemist is: niet gemeld bij de kwaliteitscontrole, én niet zichtbaar op de kwaliteitscontrole-foto's die je hebt goedgekeurd. Toonden de foto's dat het item in orde was, of was een probleem gemeld en koos je toch voor verzenden, dan geldt de retour als bedenktijd en betaal je de retourverzending zelf. Kleine afwijkingen van leveranciersfoto's zijn normaal en geen gebrek.",
    "ret.cta": "Herroepen / bestelling annuleren →",
    "ret.footer": "Dit beleid doet geen afbreuk aan je dwingende wettelijke consumentenrechten. Toepasselijk recht: Nederland.",
    "wd.done.title": "Verzoek ontvangen",
    "wd.done.body": "We hebben je herroepingsverzoek geregistreerd en je een bevestiging gemaild. Is je item al verzonden, stuur het dan binnen 14 dagen terug — we mailen je de retourgegevens. Zodra we het hebben ontvangen en gecheckt, betalen we de productprijs terug op je saldo.",
    "wd.done.backTo": "Terug naar Flowva",
    "wd.title": "Bestelling herroepen of annuleren",
    "wd.intro.pre": "Je kunt binnen 14 dagen na ontvangst van je bestelling herroepen — geen account nodig. Vul dit in en we bevestigen per e-mail. Zie ons ",
    "wd.intro.link": "retourbeleid",
