    "orders.detail.recordedCondition.body": "Diese Qualitätskontroll- & Vermessungsfotos sind der dokumentierte Zustand deines Artikels vor dem Versand – wir bewahren sie als Nachweis auf, falls du eine Rückgabe oder einen Widerruf beantragst. Bei einer Meinungsänderung wird der internationale Versand nicht erstattet; ein fehlerhafter Artikel geht auf uns. Siehe unsere Rückgaberichtlinie.",
