    "auth.err.notConfirmed": "E-Mail noch nicht bestätigt — klick auf den Link in der Mail, die wir dir geschickt haben. Nicht gefunden? Sieh im Spam-Ordner nach.",
    "common.backPlain": "Zurück",
    "ret.title": "Rückgabe & Widerruf",
    "ret.subtitle": "Deine Rechte und wie Rückgaben bei Flowva funktionieren.",
    "ret.s1.h": "1. Bei wem du kaufst",
    "ret.s1.b": "Du kaufst bei Flowva. Wir kuratieren die Produkte, legen den Preis fest, berechnen eine Servicegebühr und organisieren Einkauf, Qualitätskontrolle und internationalen Versand für dich. Flowva ist der Verkäufer.",
    "ret.s2.h": "2. Dein 14-tägiges EU-Widerrufsrecht",
    "ret.s2.b": "Du kannst innerhalb von 14 Tagen ohne Angabe von Gründen widerrufen. In der EU ist das dein gesetzliches Recht — und wir gewähren dieselben 14 Tage für jedes Land, in das wir liefern. Die 14 Tage beginnen an dem Tag, an dem du den Artikel erhältst — nicht am Bestelltag. Da Artikel aus China versendet werden, beginnt deine Frist mit Ankunft des Pakets. Du kannst auch schon vorher widerrufen.",
    "ret.s3.h": "3. So widerrufst du",
    "ret.s3.b": "Nutze die Seite „Widerrufen / Bestellung stornieren“ — kein Login nötig. Gib Namen, Bestellnummer und E-Mail an. Du erhältst automatisch eine Bestätigung und hast dann 14 Tage, um den Artikel zurückzusenden.",
    "ret.s4.h": "4. Was du erstattet bekommst",
    "ret.s4.b": "Teilrückgabe (du behältst einen Teil der Artikel): Wir erstatten nur den Produktpreis der zurückgesendeten Artikel — Versandkosten werden bei einer Teilrückgabe nicht erstattet. Vollständiger Widerruf: Produktpreis plus die Standard-Hinversandkosten.",
    "ret.s5.h": "5. Rücksendekosten",
    "ret.s5.b": "Die Rücksendung zahlst du selbst. Wir geben dir eine Rücksendeadresse in den Niederlanden — du schickst also nie nach China zurück. Innerhalb der EU sind das meist €5–€10; aus dem Vereinigten Königreich, den USA, Kanada, Australien oder Norwegen in der Regel €10–€25, je nach Versanddienst. Sende innerhalb von 14 Tagen nach deiner Anfrage zurück.",
    "ret.s6.h": "6. Zustand der Artikel",
    "ret.s6.b": "Sende Artikel im Originalzustand zurück (ungetragen, mit Etiketten und Verpackung). Bei Wertverlust durch mehr als zur Prüfung nötige Handhabung dürfen wir die Erstattung mindern.",
    "ret.s7.h": "7. Erstattung",
    "ret.s7.b": "Wir erstatten innerhalb von 14 Tagen nach Erhalt des Artikels (oder deines Versandnachweises) auf dein Flowva-Guthaben.",
    "ret.s8.h": "8. Stornieren während der Abwicklung",
    "ret.s8.b": "Bevor wir den Artikel eingekauft haben: kostenlos storniert, volle Erstattung. Nach dem Versand: wird als Rückgabe behandelt — du sendest an unsere NL-Adresse.",
    "ret.s9.h": "9. Ausgeschlossene Artikel",
    "ret.s9.b": "Das 14-Tage-Recht gilt nicht für Maß- oder personalisierte Anfertigungen, versiegelte Hygieneartikel nach dem Öffnen, verderbliche Waren und weitere gesetzlich ausgeschlossene Kategorien.",
    "ret.s10.h": "10. Defekte oder falsche Artikel",
    "ret.s10.b": "Jeder Artikel wird vor dem Versand geprüft und fotografiert. Flowva übernimmt die Rücksendekosten nur, wenn ein Artikel einen echten Defekt hat, der zweimal übersehen wurde: nicht bei der Qualitätskontrolle gemeldet und nicht auf den von dir freigegebenen Qualitätskontroll-Fotos sichtbar. Zeigten die Fotos, dass der Artikel in Ordnung war, oder wurde ein Problem gemeldet und du hast trotzdem versendet, gilt die Rücksendung als Widerruf und du zahlst die Rücksendung selbst. Kleine Abweichungen von Lieferantenfotos sind normal und kein Mangel.",
    "ret.cta": "Widerrufen / Bestellung stornieren →",
    "ret.footer": "Diese Richtlinie berührt deine zwingenden gesetzlichen Verbraucherrechte nicht. Anwendbares Recht: Niederlande.",
    "wd.done.title": "Anfrage erhalten",
    "wd.done.body": "Wir haben deinen Widerruf registriert und dir eine Bestätigung gemailt. Wurde dein Artikel bereits versendet, sende ihn innerhalb von 14 Tagen zurück — die Rücksendedaten schicken wir dir. Nach Erhalt und Prüfung erstatten wir den Produktpreis auf dein Guthaben.",
    "wd.done.backTo": "Zurück zu Flowva",
    "wd.title": "Bestellung widerrufen oder stornieren",
    "wd.intro.pre": "Du kannst innerhalb von 14 Tagen nach Erhalt deiner Bestellung widerrufen — ohne Konto. Fülle das aus und wir bestätigen per E-Mail. Siehe unsere ",
    "wd.intro.link": "Rückgaberichtlinie",
