    "auth.terms.privacy": "Politique de confidentialité",
    "auth.noAccount": "Pas encore de compte ?",
    "auth.forgot": "Mot de passe oublié ?",
    "auth.err.enterEmailFirst": "Saisis d'abord ton adresse e-mail, puis nous t'enverrons un lien.",
    "auth.success.resetSent": "Lien envoyé ! Vérifie tes e-mails pour définir un nouveau mot de passe.",
    "auth.err.alreadyExists": "Cet e-mail a déjà un compte. Passe à l'onglet « Connexion » ci-dessus — ou utilise « Mot de passe oublié ? ».",
    "auth.success.created": "Compte créé ! Vérifie tes e-mails pour confirmer. Tu ne le trouves pas ? Regarde dans tes spams.",
    "auth.err.notConfirmed": "E-mail pas encore confirmé — clique sur le lien dans l'e-mail que nous t'avons envoyé. Tu ne le trouves pas ? Regarde dans tes spams.",
    "common.backPlain": "Retour",
    "ret.title": "Retours & rétractation",
    "ret.subtitle": "Tes droits et le fonctionnement des retours chez Flowva.",
    "ret.s1.h": "1. À qui tu achètes",
    "ret.s1.b": "Tu achètes auprès de Flowva. Nous sélectionnons les produits, fixons le prix, ajoutons des frais de service et organisons l'achat, le contrôle qualité et l'expédition internationale pour toi. Flowva est le vendeur.",
    "ret.s2.h": "2. Ton droit de rétractation UE de 14 jours",
    "ret.s2.b": "Tu peux te rétracter sous 14 jours sans motif. Dans l'UE c'est ton droit légal — et nous appliquons les mêmes 14 jours pour chaque pays où nous livrons. Les 14 jours commencent le jour où tu reçois l'article — pas le jour de la commande. Comme les articles sont expédiés depuis la Chine, ton délai démarre à l'arrivée du colis. Tu peux aussi te rétracter avant son arrivée.",
    "ret.s3.h": "3. Comment te rétracter",
    "ret.s3.b": "Utilise la page « Se rétracter / annuler une commande » — sans connexion. Indique ton nom, ton numéro de commande et ton e-mail. Tu reçois une confirmation automatique, puis tu as 14 jours pour renvoyer l'article.",
    "ret.s4.h": "4. Ce qui t'est remboursé",
    "ret.s4.b": "Retour partiel (tu gardes certains articles) : nous remboursons uniquement le prix des articles renvoyés — les frais d'envoi ne sont pas remboursés pour un retour partiel. Rétractation totale : prix des produits plus les frais de livraison standard aller.",
    "ret.s5.h": "5. Frais de retour",
    "ret.s5.b": "Le renvoi est à ta charge. Nous te donnons une adresse de retour aux Pays-Bas — tu ne renvoies donc jamais vers la Chine. Dans l'UE, compte généralement €5–€10 ; depuis le Royaume-Uni, les États-Unis, le Canada, l'Australie ou la Norvège, généralement €10–€25 selon le transporteur. Renvoie sous 14 jours après ta demande.",
    "ret.s6.h": "6. État des articles",
    "ret.s6.b": "Renvoie les articles dans leur état d'origine (non portés, avec étiquettes et emballage). Nous pouvons réduire ton remboursement en cas de dépréciation due à une manipulation au-delà de ce qui est nécessaire pour inspecter l'article.",
    "ret.s7.h": "7. Remboursements",
    "ret.s7.b": "Nous remboursons sous 14 jours après réception de l'article (ou preuve d'envoi), sur ton solde Flowva.",
    "ret.s8.h": "8. Annuler pendant le traitement",
    "ret.s8.b": "Avant que nous ayons acheté l'article : annulation gratuite, remboursement intégral. Après son expédition : traité comme un retour — tu le renvoies à notre adresse NL.",
    "ret.s9.h": "9. Articles exclus",
    "ret.s9.b": "Le droit de 14 jours ne s'applique pas aux produits sur mesure ou personnalisés, aux articles d'hygiène scellés une fois descellés, aux denrées périssables et aux autres catégories exclues par la loi.",
    "ret.s10.h": "10. Articles défectueux ou erronés",
    "ret.s10.b": "Chaque article est contrôlé et photographié avant l'envoi. Flowva ne couvre le renvoi que si un article présente un vrai défaut passé inaperçu deux fois : non signalé au contrôle qualité et invisible sur les photos de contrôle qualité que tu as approuvées. Si les photos montraient que l'article était en bon état, ou si un problème avait été signalé et que tu as quand même expédié, le retour compte comme une rétractation et le renvoi est à ta charge. De légères variations par rapport aux photos du fournisseur sont normales et ne constituent pas un défaut.",
    "ret.cta": "Se rétracter / annuler une commande →",
    "ret.footer": "Cette politique ne porte pas atteinte à tes droits légaux impératifs de consommateur. Droit applicable : Pays-Bas.",
    "wd.done.title": "Demande reçue",
    "wd.done.body": "Nous avons enregistré ta demande de rétractation et envoyé une confirmation par e-mail. Si ton article a déjà été expédié, renvoie-le sous 14 jours — nous t'enverrons les détails de retour. Une fois reçu et vérifié, nous remboursons le prix du produit sur ton solde.",
    "wd.done.backTo": "Retour à Flowva",
    "wd.title": "Se rétracter ou annuler une commande",
    "wd.intro.pre": "Tu peux te rétracter sous 14 jours après réception de ta commande — sans compte. Remplis ceci et nous confirmons par e-mail. Voir notre ",
    "wd.intro.link": "politique de retours",
