    "common.backPlain": "Atrás",
    "ret.title": "Devoluciones y desistimiento",
    "ret.subtitle": "Tus derechos y cómo funcionan las devoluciones en Flowva.",
    "ret.s1.h": "1. A quién compras",
    "ret.s1.b": "Compras a Flowva. Seleccionamos los productos, fijamos el precio, añadimos una tarifa de servicio y organizamos la compra, el control de calidad y el envío internacional por ti. Flowva es el vendedor.",
    "ret.s2.h": "2. Tu derecho de desistimiento UE de 14 días",
    "ret.s2.b": "Puedes desistir en un plazo de 14 días sin dar motivos. En la UE es tu derecho legal — y aplicamos los mismos 14 días en todos los países a los que entregamos. Los 14 días empiezan el día en que recibes el artículo — no el día del pedido. Como los artículos se envían desde China, tu plazo empieza cuando llega el paquete. También puedes desistir antes de que llegue.",
    "ret.s3.h": "3. Cómo desistir",
    "ret.s3.b": "Usa la página “Desistir / cancelar pedido” — sin necesidad de cuenta. Indica tu nombre, número de pedido y correo. Recibirás una confirmación automática y tendrás 14 días para devolver el artículo.",
    "ret.s4.h": "4. Qué se te reembolsa",
    "ret.s4.b": "Devolución parcial (te quedas con parte de los artículos): reembolsamos solo el precio de los artículos devueltos — el envío no se reembolsa en una devolución parcial. Desistimiento total: precio de los productos más el coste estándar del envío de ida.",
    "ret.s5.h": "5. Gastos de devolución",
    "ret.s5.b": "Tú pagas el envío de la devolución. Te damos una dirección de devolución en los Países Bajos, así que nunca envías de vuelta a China. Dentro de la UE suele ser €5–€10; desde el Reino Unido, EE. UU., Canadá, Australia o Noruega normalmente €10–€25, según el transportista. Devuelve en un plazo de 14 días desde tu solicitud.",
    "ret.s6.h": "6. Estado de los artículos",
    "ret.s6.b": "Devuelve los artículos en su estado original (sin usar, con etiquetas y embalaje). Podemos reducir el reembolso por la pérdida de valor causada por un uso mayor del necesario para inspeccionar el artículo.",
    "ret.s7.h": "7. Reembolsos",
    "ret.s7.b": "Reembolsamos en un plazo de 14 días desde que recibimos el artículo (o tu justificante de envío), a tu saldo de Flowva.",
    "ret.s8.h": "8. Cancelar durante la tramitación",
    "ret.s8.b": "Antes de que hayamos comprado el artículo: cancelación sin coste, reembolso completo. Después de su envío: se trata como devolución — lo envías a nuestra dirección en NL.",
    "ret.s9.h": "9. Artículos excluidos",
    "ret.s9.b": "El derecho de 14 días no se aplica a productos a medida o personalizados, artículos de higiene precintados una vez abiertos, productos perecederos y otras categorías excluidas por ley.",
    "ret.s10.h": "10. Artículos defectuosos o equivocados",
    "ret.s10.b": "Cada artículo pasa control de calidad y se fotografía antes del envío. Flowva solo cubre el envío de devolución si un artículo tiene un defecto real que pasó desapercibido dos veces: no señalado en el control de calidad y no visible en las fotos de control de calidad que aprobaste. Si las fotos mostraban que el artículo estaba bien, o si un problema fue señalado y decidiste enviarlo igualmente, la devolución cuenta como desistimiento y pagas tú el envío. Pequeñas variaciones respecto a las fotos del proveedor son normales y no constituyen defecto.",
    "ret.cta": "Desistir / cancelar un pedido →",
    "ret.footer": "Esta política no afecta a tus derechos legales imperativos como consumidor. Ley aplicable: Países Bajos.",
    "wd.done.title": "Solicitud recibida",
    "wd.done.body": "Hemos registrado tu solicitud de desistimiento y te hemos enviado una confirmación por correo. Si tu artículo ya se ha enviado, devuélvelo en 14 días — te mandaremos los datos de devolución. Una vez recibido y revisado, reembolsamos el precio del producto a tu saldo.",
    "wd.done.backTo": "Volver a Flowva",
    "wd.title": "Desistir o cancelar un pedido",
    "wd.intro.pre": "Puedes desistir en los 14 días siguientes a la recepción de tu pedido — sin cuenta. Rellena esto y lo confirmaremos por correo. Consulta nuestra ",
    "wd.intro.link": "política de devoluciones",
