    "common.backPlain": "Indietro",
    "ret.title": "Resi e recesso",
    "ret.subtitle": "I tuoi diritti e come funzionano i resi su Flowva.",
    "ret.s1.h": "1. Da chi acquisti",
    "ret.s1.b": "Acquisti da Flowva. Selezioniamo i prodotti, fissiamo il prezzo, aggiungiamo una commissione di servizio e organizziamo acquisto, controllo qualità e spedizione internazionale per te. Flowva è il venditore.",
    "ret.s2.h": "2. Il tuo diritto di recesso UE di 14 giorni",
    "ret.s2.b": "Puoi recedere entro 14 giorni senza motivo. Nell'UE è un tuo diritto legale — e applichiamo gli stessi 14 giorni per ogni paese in cui consegniamo. I 14 giorni partono dal giorno in cui ricevi l'articolo — non dal giorno dell'ordine. Poiché gli articoli partono dalla Cina, il termine inizia all'arrivo del pacco. Puoi recedere anche prima dell'arrivo.",
    "ret.s3.h": "3. Come recedere",
    "ret.s3.b": "Usa la pagina “Recedi / annulla ordine” — senza login. Indica nome, numero d'ordine ed email. Riceverai una conferma automatica e avrai poi 14 giorni per rispedire l'articolo.",
    "ret.s4.h": "4. Cosa ti viene rimborsato",
    "ret.s4.b": "Reso parziale (tieni alcuni articoli): rimborsiamo solo il prezzo degli articoli resi — la spedizione non viene rimborsata per un reso parziale. Recesso totale: prezzo dei prodotti più il costo standard della consegna di andata.",
    "ret.s5.h": "5. Costi di reso",
    "ret.s5.b": "La spedizione di reso è a tuo carico. Ti diamo un indirizzo di reso nei Paesi Bassi, quindi non rispedisci mai in Cina. Nell'UE di solito costa €5–€10; dal Regno Unito, USA, Canada, Australia o Norvegia in genere €10–€25, a seconda del corriere. Rispedisci entro 14 giorni dalla richiesta.",
    "ret.s6.h": "6. Condizioni degli articoli",
    "ret.s6.b": "Restituisci gli articoli in condizioni originali (non indossati, con etichette e confezione). Possiamo ridurre il rimborso per la perdita di valore causata da un uso oltre quanto necessario per esaminare l'articolo.",
    "ret.s7.h": "7. Rimborsi",
    "ret.s7.b": "Rimborsiamo entro 14 giorni dal ricevimento del reso (o dalla prova di spedizione), sul tuo saldo Flowva.",
    "ret.s8.h": "8. Annullare durante l'elaborazione",
    "ret.s8.b": "Prima che abbiamo acquistato l'articolo: annullamento gratuito, rimborso completo. Dopo la spedizione: gestito come reso — lo rispedisci al nostro indirizzo NL.",
    "ret.s9.h": "9. Articoli esclusi",
    "ret.s9.b": "Il diritto di 14 giorni non si applica a prodotti su misura o personalizzati, articoli igienici sigillati una volta aperti, beni deperibili e altre categorie escluse per legge.",
    "ret.s10.h": "10. Articoli difettosi o sbagliati",
    "ret.s10.b": "Ogni articolo viene controllato e fotografato prima della spedizione. Flowva copre la spedizione di ritorno solo se un articolo ha un vero difetto sfuggito due volte: non segnalato al controllo qualità e non visibile nelle foto del controllo qualità che hai approvato. Se le foto mostravano che l'articolo era in ordine, o se un problema era stato segnalato e hai comunque scelto di spedire, il reso vale come recesso e paghi tu la spedizione di ritorno. Piccole variazioni rispetto alle foto del fornitore sono normali e non costituiscono difetto.",
    "ret.cta": "Recedi / annulla un ordine →",
    "ret.footer": "Questa policy non pregiudica i tuoi diritti imperativi di consumatore. Legge applicabile: Paesi Bassi.",
    "wd.done.title": "Richiesta ricevuta",
    "wd.done.body": "Abbiamo registrato la tua richiesta di recesso e ti abbiamo inviato una conferma via email. Se il tuo articolo è già stato spedito, rispediscilo entro 14 giorni — ti invieremo i dettagli per il reso. Una volta ricevuto e controllato, rimborsiamo il prezzo del prodotto sul tuo saldo.",
    "wd.done.backTo": "Torna a Flowva",
    "wd.title": "Recedi o annulla un ordine",
    "wd.intro.pre": "Puoi recedere entro 14 giorni dal ricevimento dell'ordine — senza account. Compila qui e confermeremo via email. Vedi la nostra ",
    "wd.intro.link": "policy sui resi",
    "wd.intro.post": ".",
