    "common.backPlain": "Wstecz",
    "ret.title": "Zwroty i odstąpienie",
    "ret.subtitle": "Twoje prawa i zasady zwrotów w Flowva.",
    "ret.s1.h": "1. Od kogo kupujesz",
    "ret.s1.b": "Kupujesz od Flowva. My wybieramy produkty, ustalamy cenę, doliczamy opłatę serwisową i organizujemy zakup, kontrolę jakości oraz wysyłkę międzynarodową. Flowva jest sprzedawcą.",
    "ret.s2.h": "2. Twoje unijne prawo odstąpienia — 14 dni",
    "ret.s2.b": "Możesz odstąpić od umowy w ciągu 14 dni bez podania przyczyny. W UE to Twoje prawo ustawowe — a my honorujemy te same 14 dni w każdym kraju, do którego dostarczamy. 14 dni liczy się od dnia otrzymania produktu — nie od dnia zamówienia. Ponieważ produkty są wysyłane z Chin, termin zaczyna biec, gdy paczka dotrze. Możesz też odstąpić, zanim dotrze.",
    "ret.s3.h": "3. Jak odstąpić",
    "ret.s3.b": "Skorzystaj ze strony „Odstąpienie / anulowanie zamówienia” — bez logowania. Podaj imię i nazwisko, numer zamówienia i e-mail. Otrzymasz automatyczne potwierdzenie, a potem masz 14 dni na odesłanie produktu.",
    "ret.s4.h": "4. Co otrzymasz z powrotem",
    "ret.s4.b": "Zwrot częściowy (część produktów zatrzymujesz): zwracamy tylko cenę odesłanych produktów — koszty wysyłki nie są zwracane przy zwrocie częściowym. Pełne odstąpienie: cena produktów plus standardowy koszt pierwotnej dostawy.",
    "ret.s5.h": "5. Koszty odesłania",
    "ret.s5.b": "Koszt odesłania ponosisz Ty. Podajemy adres zwrotny w Holandii, więc nigdy nie odsyłasz do Chin. W UE to zwykle €5–€10; z Wielkiej Brytanii, USA, Kanady, Australii lub Norwegii zazwyczaj €10–€25, zależnie od przewoźnika. Odeślij w ciągu 14 dni od zgłoszenia.",
    "ret.s6.h": "6. Stan produktów",
    "ret.s6.b": "Odsyłaj produkty w stanie oryginalnym (nienoszone, z metkami i opakowaniem). Możemy obniżyć zwrot o utratę wartości wynikającą z obchodzenia się z produktem ponad to, co konieczne do jego sprawdzenia.",
    "ret.s7.h": "7. Zwrot pieniędzy",
    "ret.s7.b": "Zwracamy pieniądze w ciągu 14 dni od otrzymania produktu (lub dowodu nadania) — na Twoje saldo Flowva.",
    "ret.s8.h": "8. Anulowanie w trakcie realizacji",
    "ret.s8.b": "Zanim kupimy produkt: anulowanie bez kosztów, pełny zwrot. Po wysyłce: traktowane jak zwrot — odsyłasz na nasz adres w NL.",
    "ret.s9.h": "9. Produkty wyłączone",
    "ret.s9.b": "Prawo 14 dni nie dotyczy produktów na zamówienie i personalizowanych, zapieczętowanych artykułów higienicznych po otwarciu, towarów łatwo psujących się oraz innych kategorii wyłączonych ustawowo.",
    "ret.s10.h": "10. Produkty wadliwe lub niewłaściwe",
    "ret.s10.b": "Każdy produkt przechodzi kontrolę jakości i jest fotografowany przed wysyłką. Flowva pokrywa koszt odesłania tylko wtedy, gdy produkt ma prawdziwą wadę przeoczoną dwa razy: niezgłoszoną podczas kontroli jakości i niewidoczną na zatwierdzonych przez Ciebie zdjęciach z kontroli jakości. Jeśli zdjęcia pokazywały, że produkt był w porządku, albo problem został zgłoszony, a mimo to wysłano paczkę, zwrot liczy się jako odstąpienie i sam płacisz za odesłanie. Drobne różnice względem zdjęć dostawcy są normalne i nie stanowią wady.",
    "ret.cta": "Odstąpienie / anulowanie zamówienia →",
    "ret.footer": "Ta polityka nie narusza Twoich bezwzględnie obowiązujących praw konsumenta. Prawo właściwe: Holandia.",
    "wd.done.title": "Zgłoszenie otrzymane",
    "wd.done.body": "Zarejestrowaliśmy Twoje odstąpienie i wysłaliśmy potwierdzenie e-mailem. Jeśli produkt już został wysłany, odeślij go w ciągu 14 dni — prześlemy dane do zwrotu. Po otrzymaniu i sprawdzeniu zwracamy cenę produktu na Twoje saldo.",
    "wd.done.backTo": "Wróć do Flowvy",
    "wd.title": "Odstąpienie lub anulowanie zamówienia",
    "wd.intro.pre": "Możesz odstąpić w ciągu 14 dni od otrzymania zamówienia — bez konta. Wypełnij formularz, a potwierdzimy e-mailem. Zobacz naszą ",
