    "common.backPlain": "Voltar",
    "ret.title": "Devoluções e livre resolução",
    "ret.subtitle": "Os teus direitos e como funcionam as devoluções na Flowva.",
    "ret.s1.h": "1. A quem compras",
    "ret.s1.b": "Compras à Flowva. Nós selecionamos os produtos, definimos o preço, cobramos uma taxa de serviço e tratamos da compra, do controlo de qualidade e do envio internacional por ti. A Flowva é o vendedor.",
    "ret.s2.h": "2. O teu direito UE de livre resolução de 14 dias",
    "ret.s2.b": "Podes resolver o contrato no prazo de 14 dias sem indicar motivo. Na UE é o teu direito legal — e aplicamos os mesmos 14 dias em todos os países para onde entregamos. Os 14 dias começam no dia em que recebes o artigo — não no dia da encomenda. Como os artigos são enviados da China, o prazo começa quando a encomenda chega. Também podes desistir antes de chegar.",
    "ret.s3.h": "3. Como exercer",
    "ret.s3.b": "Usa a página “Desistir / cancelar encomenda” — sem login. Indica o teu nome, número de encomenda e e-mail. Recebes uma confirmação automática e tens depois 14 dias para devolver o artigo.",
    "ret.s4.h": "4. O que é reembolsado",
    "ret.s4.b": "Devolução parcial (ficas com parte dos artigos): reembolsamos apenas o preço dos artigos devolvidos — o envio não é reembolsado numa devolução parcial. Resolução total: preço dos produtos mais o custo padrão do envio inicial.",
    "ret.s5.h": "5. Custos de devolução",
    "ret.s5.b": "O envio de devolução é pago por ti. Damos-te uma morada de devolução nos Países Baixos, por isso nunca envias de volta para a China. Na UE costuma ser €5–€10; do Reino Unido, EUA, Canadá, Austrália ou Noruega normalmente €10–€25, consoante a transportadora. Devolve no prazo de 14 dias após o pedido.",
    "ret.s6.h": "6. Estado dos artigos",
    "ret.s6.b": "Devolve os artigos no estado original (não usados, com etiquetas e embalagem). Podemos reduzir o reembolso pela perda de valor causada por manuseamento além do necessário para inspecionar o artigo.",
    "ret.s7.h": "7. Reembolsos",
    "ret.s7.b": "Reembolsamos no prazo de 14 dias após recebermos o artigo (ou o comprovativo de envio), para o teu saldo Flowva.",
    "ret.s8.h": "8. Cancelar durante o processamento",
    "ret.s8.b": "Antes de comprarmos o artigo: cancelamento sem custos, reembolso total. Depois de enviado: tratado como devolução — devolves para a nossa morada nos Países Baixos.",
    "ret.s9.h": "9. Artigos excluídos",
    "ret.s9.b": "O direito de 14 dias não se aplica a produtos por medida ou personalizados, artigos de higiene selados depois de abertos, bens perecíveis e outras categorias excluídas por lei.",
    "ret.s10.h": "10. Artigos com defeito ou errados",
    "ret.s10.b": "Cada artigo passa por controlo de qualidade e é fotografado antes do envio. A Flowva só cobre o envio de devolução se um artigo tiver um verdadeiro defeito que passou despercebido duas vezes: não sinalizado no controlo de qualidade e não visível nas fotos de controlo de qualidade que aprovaste. Se as fotos mostravam que o artigo estava em ordem, ou se um problema foi sinalizado e decidiste enviar na mesma, a devolução conta como retratação e pagas tu o envio de volta. Pequenas variações face às fotos do fornecedor são normais e não constituem defeito.",
    "ret.cta": "Desistir / cancelar uma encomenda →",
    "ret.footer": "Esta política não afeta os teus direitos legais imperativos de consumidor. Lei aplicável: Países Baixos.",
    "wd.done.title": "Pedido recebido",
    "wd.done.body": "Registámos o teu pedido de livre resolução e enviámos-te uma confirmação por e-mail. Se o teu artigo já foi enviado, devolve-o no prazo de 14 dias — enviaremos os dados de devolução. Depois de recebido e verificado, reembolsamos o preço do produto para o teu saldo.",
    "wd.done.backTo": "Voltar à Flowva",
    "wd.title": "Desistir ou cancelar uma encomenda",
    "wd.intro.pre": "Podes desistir no prazo de 14 dias após receberes a encomenda — sem conta. Preenche isto e confirmamos por e-mail. Vê a nossa ",
    "wd.intro.link": "política de devoluções",
